import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_auth/firebase_auth.dart';import '../models/user_profile_model.dart';class ProfileRemoteDataSource{final FirebaseFirestore firestore;final FirebaseAuth auth;ProfileRemoteDataSource({required this.firestore,required this.auth});String get uid=>auth.currentUser?.uid??(throw Exception('User is not authenticated.'));DocumentReference<Map<String,dynamic>> get ref=>firestore.collection('users').doc(uid);Future<UserProfileModel> getProfile()async{final d=await ref.get();if(!d.exists){final u=auth.currentUser!;await ref.set({'displayName':u.displayName??'','email':u.email??'','createdAt':FieldValue.serverTimestamp(),'updatedAt':FieldValue.serverTimestamp()});}return UserProfileModel.fromDoc(await ref.get());}Future<UserProfileModel> updateProfile(UserProfileModel p)async{await ref.set(p.toMap(),SetOptions(merge:true));await auth.currentUser?.updateDisplayName(p.displayName);return UserProfileModel.fromDoc(await ref.get());}}
